template<class Value> bool presentationRange(Effect e,const std::string &id,Value value,double &lo,double &hi) {
 if(e==Effect::Base && id=="toeStart") {lo=-20.0;hi=std::min(double(4.0),double(value("shoulderStart",0)));return true;}
 if(e==Effect::Base && id=="shoulderStart") {lo=std::max(double(-4.0),double(value("toeStart",0)));hi=20.0;return true;}
 if(e==Effect::Base && id=="shadowRange") {lo=-20.0;hi=std::min(double(4.0),double(value("highlightRange",0)));return true;}
 if(e==Effect::Base && id=="highlightRange") {lo=std::max(double(-4.0),double(value("shadowRange",0)));hi=20.0;return true;}
 return false;
}
